<template>
  <div class="teacher"><AppNav/><main v-loading="loading">
    <header><div><small>TEACHER CONSOLE</small><h1>教师工作台</h1></div><el-select v-model="courseId" placeholder="选择负责课程" @change="loadCourse"><el-option v-for="c in dashboard.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button @click="courseDialog=true">创建任教课程</el-button></header>
    <section class="stats"><article>负责课程 <b>{{ dashboard.summary.course_count }}</b></article><article>课程任务 <b>{{ dashboard.summary.task_count }}</b></article><article>待批改 <b>{{ dashboard.summary.pending_grading }}</b></article></section>
    <el-empty v-if="!dashboard.courses.length" description="尚无任教课程，点击“创建任教课程”开始教学"/>
    <el-tabs v-else v-model="tab">
      <el-tab-pane label="课程总览" name="overview"><h2>{{ currentCourse?.name }}</h2><p>负责教师：{{ currentCourse?.teacher || '课程教师' }} · {{ resources.length }} 份资料</p><p>自行创建任教课程后，即可管理任务、资料、通知和本课程学生。已有课程由原授权教师管理。</p><p>{{ analytics.notice }}</p><section class="stats"><article>加入学生 <b>{{ analytics.student_count }}</b></article><article>已发布任务 <b>{{ analytics.published_tasks }}</b></article><article>需跟进 <b>{{ analytics.at_risk_students?.length }}</b></article></section><div class="actions"><el-tag v-if="currentCourse?.archived_at" type="warning">已归档</el-tag><el-button @click="toggleArchive">{{ currentCourse?.archived_at ? '恢复课程' : '归档课程' }}</el-button><el-button type="danger" plain @click="deleteCourse">删除课程</el-button></div></el-tab-pane>
      <el-tab-pane label="任务与批改" name="tasks">
        <el-form label-position="top"><el-form-item label="任务标题"><el-input v-model="task.title" maxlength="160"/></el-form-item><el-form-item label="任务要求"><el-input v-model="task.description" type="textarea" :rows="4" maxlength="4000"/></el-form-item><el-form-item label="类型"><el-select v-model="task.task_type"><el-option v-for="(label,key) in types" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="截止时间（可选）"><el-date-picker v-model="task.due_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-button :disabled="busy" @click="saveTask(false)">保存草稿</el-button><el-button type="primary" :disabled="busy" @click="saveTask(true)">发布任务</el-button></el-form>
        <article v-for="t in tasks" :key="t.id"><h3>{{ t.title }} <el-tag>{{ t.published ? '已发布' : '草稿' }}</el-tag></h3><p>{{ t.description }}</p><small>{{ types[t.task_type] }} · {{ t.submission_count }} 份提交 · {{ t.pending_count }} 份待批改 · 截止 {{ date(t.due_at) }}</small><div class="actions"><el-button v-if="!t.published" :disabled="busy" @click="mutate(`/teacher/tasks/${t.id}/publish`,'PATCH')">发布</el-button><el-button @click="showSubmissions(t)">查看提交与评分</el-button><el-button @click="exportGrades(t)">导出成绩 CSV</el-button></div></article><el-empty v-if="!tasks.length" description="暂无任务"/>
      </el-tab-pane>
      <el-tab-pane label="资料审核" name="resources"><p>审核状态为质量标记，保留现有学生资料访问方式。</p><article v-for="r in resources" :key="r.id"><h3>{{ r.title }} <el-tag>{{ r.review_status }}</el-tag></h3><p>{{ r.description }}</p><small>{{ r.file_name || r.type }}</small><div class="actions"><el-button v-if="r.file_path" @click="preview(r)">查看文件</el-button><a v-else-if="safeLink(r.url)" :href="r.url" target="_blank" rel="noopener noreferrer">查看链接</a><el-button v-for="(label,status) in reviews" :key="status" :disabled="busy" @click="mutate(`/teacher/resources/${r.id}/review`,'PATCH',{status})">{{ label }}</el-button></div></article><el-empty v-if="!resources.length" description="暂无资料"/></el-tab-pane>
      <el-tab-pane label="课程通知" name="notices"><el-form label-position="top"><el-form-item label="通知标题"><el-input v-model="notice.title" maxlength="100"/></el-form-item><el-form-item label="通知内容"><el-input v-model="notice.content" type="textarea" :rows="4" maxlength="3000"/></el-form-item><el-checkbox v-model="notice.is_pinned">置顶</el-checkbox><el-button type="primary" :disabled="busy" @click="saveNotice">发布通知</el-button></el-form><article v-for="n in notices" :key="n.id"><h3>{{ n.is_pinned ? '置顶 · ' : '' }}{{ n.title }}</h3><p>{{ n.content }}</p><small>{{ date(n.created_at) }}</small></article><el-empty v-if="!notices.length" description="暂无通知"/></el-tab-pane>
      <el-tab-pane label="班级统计与跟进" name="analytics"><p>{{ analytics.notice }}</p><el-table :data="analytics.students || []"><el-table-column prop="name" label="学生"/><el-table-column prop="account" label="学号"/><el-table-column label="任务完成"><template #default="{row}">{{ row.completed }}/{{ row.total }}</template></el-table-column><el-table-column prop="average_score" label="平均分"/><el-table-column label="跟进"><template #default="{row}"><el-tag :type="row.at_risk?'warning':'success'">{{ row.at_risk?'需跟进':'正常' }}</el-tag><el-button @click="note.student_id=row.student_id">写备注</el-button></template></el-table-column></el-table><h3>预警学生</h3><p>{{ (analytics.at_risk_students || []).map(s=>s.name).join('、') || '暂无预警' }}</p><h3>教师私有跟进备注</h3><el-select v-model="note.student_id" placeholder="选择本课程学生"><el-option v-for="s in analytics.students" :key="s.student_id" :label="`${s.name}（${s.account}）`" :value="s.student_id"/></el-select><el-input v-model="note.content" type="textarea" :rows="3" maxlength="3000" placeholder="仅本人可见"/><el-button :disabled="busy" @click="saveNote">保存备注</el-button><article v-for="n in notes" :key="n.id"><b>{{ n.student_name }}</b><p>{{ n.content }}</p><small>{{ date(n.created_at) }}</small></article></el-tab-pane>
      <el-tab-pane label="成员与邀请码" name="members"><p v-if="currentCourse">课程空间：{{ currentCourse.name }}-{{ currentCourse.college }}-{{ currentCourse.class_name }}-{{ currentCourse.teacher }}</p><p class="invite-code">邀请码：<b>{{ courseSpace.invite_code || '加载中' }}</b><el-button size="small" @click="copyInvite">复制</el-button><el-button size="small" @click="regenerateInvite">更新邀请码</el-button><el-button size="small" @click="syncMembers">同步匹配学生</el-button></p><p><small v-if="courseSpace.expires_at">有效期至 {{ date(courseSpace.expires_at) }}</small><small v-if="courseSpace.max_uses"> · 已批准 {{ courseSpace.uses || 0 }}/{{ courseSpace.max_uses }}</small></p><el-checkbox v-model="reviewRequired" @change="saveReviewRequired">新材料需审核后才进入 AI 检索</el-checkbox><h3>助教</h3><div class="actions"><span v-for="a in assistants" :key="a.id" class="assistant">{{ a.name }} <button type="button" @click="removeAssistant(a)">×</button></span><el-select v-model="assistantId" placeholder="选择教师" size="small" style="width:180px"><el-option v-for="t in assistantCandidates" :key="t.id" :label="t.name" :value="t.id"/></el-select><el-button size="small" @click="addAssistant">添加助教</el-button></div><h3>待审核申请</h3><article v-for="r in joinRequests.filter(item=>item.status==='pending')" :key="r.id" class="request"><span>{{ r.name }}（{{ r.student_id }}）<small>{{ r.college }} · {{ r.class }}</small></span><span><el-button size="small" type="success" @click="reviewJoin(r,'approve')">通过</el-button><el-button size="small" @click="reviewJoin(r,'reject')">拒绝</el-button></span></article><el-empty v-if="!joinRequests.filter(item=>item.status==='pending').length" description="暂无待审核申请"/><h3>已加入成员</h3><article v-for="m in members" :key="m.id" class="request"><span>{{ m.name }}（{{ m.student_id }}）<small>{{ m.college }} · {{ m.class }}</small></span><span><el-button size="small" @click="addFriend(m.id)" :disabled="m.is_friend || m.friend_request_pending">{{ m.is_friend ? '已是好友' : m.friend_request_pending ? '已申请' : '加好友' }}</el-button><el-button size="small" type="danger" plain @click="removeMember(m)">移出</el-button></span></article></el-tab-pane>
      <el-tab-pane label="课程论坛" name="forum"><article v-for="p in posts" :key="p.id"><h3>{{ p.title }}</h3><small>{{ p.author_name }}</small><p>{{ p.content }}</p><el-input v-model="p.teacher_reply" type="textarea" :rows="3" maxlength="3000" placeholder="教师答复"/><div class="actions"><el-checkbox v-model="p.teacher_pinned" :true-value="1" :false-value="0">置顶</el-checkbox><el-select v-model="p.teacher_status"><el-option label="开放" value="open"/><el-option label="关闭讨论" value="closed"/><el-option label="隐藏" value="hidden"/></el-select><el-button :disabled="busy" @click="mutate(`/teacher/forum/posts/${p.id}`,'PATCH',{reply:p.teacher_reply,is_pinned:!!p.teacher_pinned,status:p.teacher_status})">保存答复与状态</el-button></div></article><el-empty v-if="!posts.length" description="本课程暂无帖子"/></el-tab-pane>
      <el-tab-pane label="AI 教学建议" name="ai"><el-alert title="仅使用本课程匿名统计生成草稿，不自动发布任务或成绩。使用教师自己的模型配置。" :closable="false"/><el-button type="primary" :loading="aiBusy" @click="generateAdvice">生成教学建议草稿</el-button><article v-if="advice"><h3>AI 教学建议 · 草稿待审核</h3><p>{{ advice.content }}</p><small>{{ advice.notice }}</small><p>依据：{{ advice.basis }}</p></article></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="courseDialog" title="创建任教课程" width="min(500px,94vw)"><el-form label-position="top"><el-form-item label="课程名称"><el-input v-model="courseName" maxlength="100" placeholder="例如：数据结构"/></el-form-item><el-form-item label="学院"><el-input v-model="courseCollege" maxlength="100" placeholder="例如：计算机科学与技术学院"/></el-form-item><el-form-item label="班级"><el-input v-model="courseClass" maxlength="100" placeholder="例如：软件工程 1 班"/></el-form-item></el-form><template #footer><el-button :loading="creatingCourse" @click="createCourse">创建课程空间</el-button></template></el-dialog>
    <el-dialog v-model="gradingDialog" :title="`任务提交：${selectedTask?.title || ''}`" width="min(800px,94vw)"><article v-for="s in submissions" :key="s.id"><b>{{ s.student_name }}（{{ s.student_id }}）</b><p>{{ s.content }}</p><small>{{ date(s.submitted_at) }}</small><el-form label-position="top"><el-form-item label="分数 0–100"><el-input-number v-model="s.editScore" :min="0" :max="100"/></el-form-item><el-form-item label="教师反馈"><el-input v-model="s.editFeedback" type="textarea" maxlength="3000"/></el-form-item><el-button :disabled="busy" @click="grade(s)">保存评分和反馈</el-button></el-form></article><el-empty v-if="!submissions.length" description="暂无提交"/></el-dialog>
  </main></div>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import AppNav from '../components/AppNav.vue'
import {api, downloadFile} from '../utils/api'
const dashboard=ref({courses:[],summary:{}}),courseId=ref(),tab=ref('overview'),loading=ref(false),busy=ref(false),aiBusy=ref(false)
const tasks=ref([]),resources=ref([]),notices=ref([]),analytics=ref({}),notes=ref([]),posts=ref([]),advice=ref(null),submissions=ref([]),selectedTask=ref(null),gradingDialog=ref(false),joinRequests=ref([]),members=ref([]),courseSpace=ref({}),assistants=ref([]),assistantCandidates=ref([]),assistantId=ref(null),reviewRequired=ref(false)
const freshTask=()=>({title:'',description:'',task_type:'assignment',due_at:''})
const task=ref(freshTask()),notice=ref({title:'',content:'',is_pinned:false}),note=ref({student_id:null,content:''})
const currentCourse=computed(()=>dashboard.value.courses.find(c=>c.id===courseId.value))
const types={practice:'练习',reading:'阅读',assignment:'作业',discussion:'讨论'},reviews={approved:'通过',pending:'待审核',rejected:'驳回'}
const date=v=>v?new Date(v).toLocaleString('zh-CN'):'未设置'
const safeLink=v=>/^https?:\/\//i.test(v||'')
let generation=0
async function loadCourse(){const version=++generation,id=courseId.value;tasks.value=[];resources.value=[];notices.value=[];analytics.value={};notes.value=[];posts.value=[];joinRequests.value=[];members.value=[];courseSpace.value={};assistants.value=[];assistantCandidates.value=[];reviewRequired.value=false;advice.value=null;submissions.value=[];gradingDialog.value=false;task.value=freshTask();notice.value={title:'',content:'',is_pinned:false};note.value={student_id:null,content:''};if(!id)return;loading.value=true;try{const result=await Promise.all([api(`/teacher/courses/${id}/tasks`),api(`/teacher/courses/${id}/resources`),api(`/courses/${id}/announcements`),api(`/teacher/courses/${id}/analytics`),api(`/teacher/courses/${id}/notes`),api('/teacher/forum/posts'),api(`/courses/${id}/space`),api(`/teacher/courses/${id}/join-requests`),api(`/courses/${id}/members`),api(`/teacher/courses/${id}/assistants`),api('/teachers')]);if(version!==generation)return;[tasks.value,resources.value,notices.value,analytics.value,notes.value]=result;posts.value=result[5].filter(p=>p.course_id===id);courseSpace.value=result[6].space||{};joinRequests.value=result[7];members.value=result[8].members||[];assistants.value=result[9];assistantCandidates.value=result[10].filter(t=>!result[9].some(a=>a.id===t.id));reviewRequired.value=Boolean(result[6].course?.review_required)}catch(e){ElMessage.error(e.message)}finally{if(version===generation)loading.value=false}}
async function load(){try{dashboard.value=await api('/teacher/dashboard');courseId.value??=dashboard.value.courses[0]?.id;await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function mutate(path,method,body){if(busy.value)return false;busy.value=true;try{const result=await api(path,{method,body:body?JSON.stringify(body):undefined});ElMessage.success(result.message||'已保存');dashboard.value=await api('/teacher/dashboard');await loadCourse();return true}catch(e){ElMessage.error(e.message);return false}finally{busy.value=false}}
function saveTask(published){if(!task.value.title.trim())return ElMessage.warning('请输入任务标题');return mutate(`/teacher/courses/${courseId.value}/tasks`,'POST',{...task.value,published})}
function saveNotice(){if(!notice.value.title.trim()||!notice.value.content.trim())return ElMessage.warning('请填写标题和内容');return mutate(`/teacher/courses/${courseId.value}/announcements`,'POST',notice.value)}
function saveNote(){if(!note.value.student_id||!note.value.content.trim())return ElMessage.warning('请选择学生并填写备注');return mutate(`/teacher/courses/${courseId.value}/notes`,'POST',note.value)}
async function showSubmissions(t){const id=courseId.value;try{const result=await api(`/teacher/tasks/${t.id}/submissions`);if(id!==courseId.value)return;selectedTask.value=t;submissions.value=result.map(s=>({...s,editScore:s.score,editFeedback:s.feedback}));gradingDialog.value=true}catch(e){ElMessage.error(e.message)}}
async function grade(s){if(typeof s.editScore!=='number')return ElMessage.warning('请输入分数');busy.value=true;try{await api(`/teacher/submissions/${s.id}/grade`,{method:'PATCH',body:JSON.stringify({score:s.editScore,feedback:s.editFeedback})});ElMessage.success('评分已保存');dashboard.value=await api('/teacher/dashboard')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function preview(r){try{const response=await fetch(`/api/teacher/resources/${r.id}/file`,{headers:{Authorization:`Bearer ${localStorage.getItem('token')}`}});if(!response.ok)throw new Error('无法打开文件');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=r.file_name||r.title;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){ElMessage.error(e.message)}}
async function generateAdvice(){const id=courseId.value;aiBusy.value=true;advice.value=null;try{const result=await api(`/teacher/courses/${id}/ai-advice`,{method:'POST'});if(id===courseId.value)advice.value=result}catch(e){ElMessage.error(e.message)}finally{aiBusy.value=false}}
const courseDialog=ref(false),courseName=ref(''),courseCollege=ref(''),courseClass=ref(''),creatingCourse=ref(false)
async function createCourse(){if(!courseName.value.trim()||!courseCollege.value.trim()||!courseClass.value.trim())return ElMessage.warning('请填写课程名称、学院和班级');creatingCourse.value=true;try{const result=await api('/teacher/courses',{method:'POST',body:JSON.stringify({name:courseName.value,college:courseCollege.value,class_name:courseClass.value})});courseId.value=result.id;courseDialog.value=false;courseName.value='';courseCollege.value='';courseClass.value='';await load();ElMessage.success(`${result.message}，邀请码：${result.invite_code}`)}catch(e){ElMessage.error(e.message)}finally{creatingCourse.value=false}}
async function reviewJoin(request,action){try{const result=await api(`/teacher/course-join-requests/${request.id}`,{method:'PATCH',body:JSON.stringify({action})});ElMessage.success(result.message);await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function syncMembers(){try{const result=await api(`/teacher/courses/${courseId.value}/sync-members`,{method:'POST'});ElMessage.success(`${result.message}：${result.auto_enrolled} 人`);await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function regenerateInvite(){const days=window.prompt('有效期（天，默认 14）','14');if(days===null)return;const maxUses=window.prompt('最多可批准人数（0 为不限）','0');if(maxUses===null)return;try{const result=await api(`/teacher/courses/${courseId.value}/regenerate-invite`,{method:'POST',body:JSON.stringify({expires_days:Number(days),max_uses:Number(maxUses)})});courseSpace.value={...courseSpace.value,invite_code:result.invite_code,expires_at:result.expires_at,max_uses:result.max_uses,uses:0};ElMessage.success(result.message)}catch(e){ElMessage.error(e.message)}}
async function copyInvite(){try{await navigator.clipboard.writeText(courseSpace.value.invite_code);ElMessage.success('邀请码已复制')}catch{ElMessage.info(courseSpace.value.invite_code)}}
async function saveReviewRequired(){try{const result=await api(`/teacher/courses/${courseId.value}/resource-review`,{method:'PATCH',body:JSON.stringify({required:reviewRequired.value})});ElMessage.success(result.message)}catch(e){ElMessage.error(e.message)}}
async function addAssistant(){if(!assistantId.value)return ElMessage.warning('请选择教师');try{const result=await api(`/teacher/courses/${courseId.value}/assistants`,{method:'POST',body:JSON.stringify({user_id:assistantId.value})});assistantId.value=null;ElMessage.success(result.message);await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function removeAssistant(a){try{if(!window.confirm(`移除助教“${a.name}”？`))return;const result=await api(`/teacher/courses/${courseId.value}/assistants/${a.id}`,{method:'DELETE'});ElMessage.success(result.message);await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function removeMember(m){try{if(!window.confirm(`将“${m.name}”移出课程？`))return;const result=await api(`/teacher/courses/${courseId.value}/members/${m.id}`,{method:'DELETE'});ElMessage.success(result.message);await loadCourse()}catch(e){ElMessage.error(e.message)}}
async function toggleArchive(){const archived=!currentCourse.value?.archived_at;try{const result=await api(`/teacher/courses/${courseId.value}/archive`,{method:'PATCH',body:JSON.stringify({archived})});ElMessage.success(result.message);await load()}catch(e){ElMessage.error(e.message)}}
async function deleteCourse(){if(!window.confirm('永久删除课程及其资料、作业和群聊？该操作不可撤销。'))return;try{const result=await api(`/teacher/courses/${courseId.value}`,{method:'DELETE'});ElMessage.success(result.message);courseId.value=null;await load()}catch(e){ElMessage.error(e.message)}}
async function exportGrades(t){try{await downloadFile(`/teacher/tasks/${t.id}/submissions.csv`,`task-${t.id}-submissions.csv`)}catch(e){ElMessage.error(e.message)}}
async function addFriend(userId){try{const result=await api('/friend-requests',{method:'POST',body:JSON.stringify({user_id:userId})});ElMessage.success(result.message);await loadCourse()}catch(e){ElMessage.error(e.message)}}
onMounted(load)
</script>
<style scoped>
.teacher{min-height:100vh;background:#fffaf6;color:#633e2e}main{width:min(1120px,94vw);margin:auto;padding:36px 0 70px}header,.actions{display:flex;gap:12px;align-items:center;justify-content:space-between}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stats b{display:block;font-size:28px}article{background:white;border:1px solid #eeddd3;border-radius:14px;padding:18px;margin:14px 0}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}small{color:#987a6a}.actions{justify-content:flex-start;flex-wrap:wrap;margin-top:12px}.assistant{display:inline-flex;gap:5px;align-items:center;background:#f5ede4;border-radius:9px;padding:3px 7px;font-size:12px}.assistant button{border:0;background:transparent;color:#a4503a;cursor:pointer}.invite-code{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.el-textarea{margin:12px 0}.el-form{max-width:750px;margin:18px 0}@media(max-width:650px){.stats{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}}
</style>
